import{_ as o,o as t,c as a,a3 as i}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"Production Control and Frontier Research","description":"","frontmatter":{"translationSource":{"title":"生产控制与前沿研究","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0iirIEzxWlkfel2jMLIWJJ","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/production-control-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/production-control-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/production-control-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/production-control-and-frontier-research"}]]},"headers":[],"relativePath":"production-control-and-frontier-research.md","filePath":"logistics/src/page-0iirIEzxWlkfel2jMLIWJJ.md"}'),n={name:"production-control-and-frontier-research.md"};function r(s,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><h1 id="production-control-and-frontier-research" tabindex="-1">Production Control and Frontier Research <a class="header-anchor" href="#production-control-and-frontier-research" aria-label="Permalink to &quot;Production Control and Frontier Research&quot;">​</a></h1><blockquote><p>Source page ID: <code>0iirIEzxWlkfel2jMLIWJJ</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0iirIEzxWlkfel2jMLIWJJ" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5515548b0ac8f945.q90-2df7f7103be0fb88.webp" alt="Production Control and Frontier Research"></p><p><span id="source-block-DWqjx1xibQYINqsd5UEFOm"></span></p><h2 id="principles-of-blocking-control-also-known-as-production-controlled-by-blocking-or-full-storage-dynamics" tabindex="-1">Principles of Blocking Control (Also Known as Production Controlled by Blocking, or Full-Storage Dynamics) <a class="header-anchor" href="#principles-of-blocking-control-also-known-as-production-controlled-by-blocking-or-full-storage-dynamics" aria-label="Permalink to &quot;Principles of Blocking Control (Also Known as Production Controlled by Blocking, or Full-Storage Dynamics)&quot;">​</a></h2><p>(Coo coo coo... this large work is under construction. Graduation work is keeping me busy, so updates are slowing.)</p><p><a href="https://www.skland.com/article?id=6331180" target="_blank" rel="noreferrer">jnk&#39;s introductory article</a></p><p><a href="/endfield-skydoc/explanation-automatically-balanced-production-lines-and-adaptive-devices">Explanation: Automatically Balanced Production Lines and Adaptive Devices</a></p><p>Author: kokobird (Sections 1–5). Contact me with questions.</p><details><summary>bilibili</summary><p>蓝海露花_kokobird. I rarely check bilibili, though; finding me in the group is easier.</p></details><p>Last updated: November 3, 2026 (\\today)</p><p>Status: Section 5 is slowly under construction. I am trying to find time to organize and supplement Sections 1 and 2.</p><p><span id="source-block-rCxnzFpo8mWaztoa5WoVYx"></span></p><h3 id="_1-introduction" tabindex="-1">1 Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;1 Introduction&quot;">​</a></h3><p><span class="mark-rose_red">Welcome to the automatic-production classroom, Endministrator. Perhaps you have just built simple recipe-based lines and are eager for advanced material; perhaps you can already independently plan and lay out every region&#39;s factory and are idly browsing. Either way, I hope this article offers theoretical or practical inspiration in your spare time and shows the distinctive appeal of Endfield&#39;s industry. Perhaps someday you too will build an unusual production line and pioneer a new school of factory design.</span></p><p><a href="/endfield-skydoc/1-1-so-tell-me-what-is-production-controlled-by-blocking">1.1 So Tell Me, What Is Blocking Control?</a> · <a href="/endfield-skydoc/1-2-what-are-the-benefits-of-blocking-based-production">1.2 What Are the Benefits of Blocking Control?</a> · <a href="/endfield-skydoc/1-3-glossary">1.3 Glossary (Even I Cannot Fully Define These; You Can Skip It)</a> · <a href="/endfield-skydoc/1-4-prerequisite-basics">1.4 Prerequisite Knowledge (To Be Written)</a></p><p><span id="source-block-9lRjFmYbvOxK5tFFbqXsuJ"></span></p><h3 id="_2-basic-concepts-and-simple-examples-of-blocking-control" tabindex="-1">2 Basic Concepts and Simple Examples of Blocking Control <a class="header-anchor" href="#_2-basic-concepts-and-simple-examples-of-blocking-control" aria-label="Permalink to &quot;2 Basic Concepts and Simple Examples of Blocking Control&quot;">​</a></h3><p>This section introduces basic concepts and simple examples of blocking control. Understanding it lets you design blocking-based production plans for <span class="mark-rose_red"><strong>multiple products made from a single input material</strong></span>, covering most simple automatic-production needs. <strong>If you think you already understand this material, read through 2.5; if you can follow it, go straight to Section 3.</strong></p><p>It is worth making clear at the outset that blocking control usually involves two stages: <span class="mark-rose_red"><strong>theoretical planning</strong></span> and <span class="mark-rose_red"><strong>engineering implementation</strong></span>. During <span class="mark-rose_red"><strong>theoretical planning</strong></span>, we discuss <u>which products to make, how much input material is needed, which production steps to use, how materials should flow and be distributed, and how priorities should be designed</u>. For example, our analysis may show that out of 120 Ferrium, X should be shredded and Y used for Yazhen Syringes [C], but at this stage we are not particularly concerned with how to build a line that shreds X Ferrium.</p><p>In <span class="mark-rose_red"><strong>engineering implementation</strong></span>, we discuss <u>facility layout, the particular structures implementing priority, and structural optimization</u>. With sufficient <span class="mark-rose_red"><strong>theoretical planning</strong></span>, implementation usually amounts to wiring the planned connections. Optimizing those connections is outside this article&#39;s focus, though it still takes considerable skill. Most subsequent analysis therefore emphasizes <span class="mark-rose_red"><strong>theoretical planning</strong></span>; commonly used implementation structures appear in the appendix.</p><p><a href="/endfield-skydoc/2-1-hello-world-ferrium-ore-at-a-fork-in-the-road">2.1 Hello World: Ferrium Ore at a Fork in Its Fate</a> · <a href="/endfield-skydoc/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking">2.2 Two Blossoms: Switching-Type and Balancing-Type Blocking</a> · <a href="/endfield-skydoc/2-3-the-controlled-controlled-branch-and-the-unfree-free-branch">2.3 The Controlled Controlled Branch and the Unfree Free Branch (Considering Retirement)</a></p><p>Note: I am considering replacing “controlled branch” and “free branch” with <strong>blocking branch</strong> and <strong>flowing branch</strong>. When only splitting is considered, an external restriction controls the controlled branch, which then controls the free branch; with merging, the direction is reversed. It may therefore be better to use blocking/flowing branch and distinguish the control relationship separately. The terminology below has not yet been adjusted.</p><p><a href="/endfield-skydoc/2-3-blocking-and-flowing-branches-you-control-me-i-control-you">2.3 Blocking and Flowing Branches: You Control Me, I Control You</a> · <a href="/endfield-skydoc/2-4-faster-than-light-upstream-propagation-of-blocking-signals">2.4 “Faster-Than-Light” Upstream Propagation of Blocking Signals</a> · <a href="/endfield-skydoc/2-5-is-a-stash-not-just-a-special-splitter">2.5 Isn&#39;t a Stash Just a Special Splitter? (Core Content ⭐)</a> · <a href="/endfield-skydoc/practical-exercise-a-coupled-xircon-yazhen-syringe-line-using-120">Practical Exercise: A Coupled Xircon–Yazhen Syringe [C] Line with 120 Ferrium</a> · <a href="/endfield-skydoc/2-6-empty-storage-full-storage-we-need-more-oversupply">2.6 Empty Storage? Full Storage? We Need More Oversupply!</a> · <a href="/endfield-skydoc/appendix-common-priority-structures">Appendix: Common Priority Structures</a></p><p><span id="source-block-x00nPzaklxsQ7IkqVngiau"></span></p><h3 id="_3-advanced-blocking-control" tabindex="-1">3 Advanced Blocking Control <a class="header-anchor" href="#_3-advanced-blocking-control" aria-label="Permalink to &quot;3 Advanced Blocking Control&quot;">​</a></h3><details><summary>There is advanced material too?!</summary><p>Congratulations, builder of great production lines. By reaching this point, you have learned the basic concepts of blocking-based production: roughly what it is and how to implement it. A wider world now opens before you. Rest a moment, then soar freely and enjoy the endless possibilities.</p></details><p>This section analyzes blocking-based solutions to harder demands, including <strong>adaptive balancing with multiple inputs and multiple products, and zero-waste blocking-based production using Solid-Gas and Fluid-Gas Transmuting Units</strong>. Understanding it helps you combine these principles with new demands introduced by updates, meet more complex production needs, and understand the dynamics of blocking-based production more deeply.</p><p><a href="/endfield-skydoc/3-0-balancing-adaptation-maximum-value-output-what-are-you-talking-about">3.0 Balancing, Adaptive Operation, Maximum-Value Output—What Are You Babbling About?</a> · <a href="/endfield-skydoc/3-1-the-beginnings-of-automatic-balancing-xiranite-and-originium-powders">3.1 The Beginnings of Automatic Balancing: Xiranite and Originium Powder&#39;s Love–Hate Relationship</a> · <a href="/endfield-skydoc/3-2-the-highest-mountain-heavy-xiranite-and-pyrrolite">3.2 The Highest Mountain?! Heavy Xiranite AND Pyrrolite</a> · <a href="/endfield-skydoc/3-3-you-you-xiranite-freeloading-pig">3.3 You... You Xiranite-Gobbling Pig!</a></p><p><span id="source-block-V0u4t2MI93uTva23MwciTO"></span></p><h4 id="_3-4-switch-from-sc-to-lc-batteries-when-sc-storage-fills-from-hetonite-to-pyrrolite-when-hetonite-storage-fills-etc" tabindex="-1">3.4 Switch from SC to LC Batteries When SC Storage Fills, from Hetonite to Pyrrolite When Hetonite Storage Fills, etc. <a class="header-anchor" href="#_3-4-switch-from-sc-to-lc-batteries-when-sc-storage-fills-from-hetonite-to-pyrrolite-when-hetonite-storage-fills-etc" aria-label="Permalink to &quot;3.4 Switch from SC to LC Batteries When SC Storage Fills, from Hetonite to Pyrrolite When Hetonite Storage Fills, etc.&quot;">​</a></h4><p>Consider moving this to <a href="/endfield-skydoc/automatic-switching-for-reactions-with-multiple-raw-materials">Automatic Switching for Reactions with Multiple Input Materials</a></p><p><a href="https://www.bilibili.com/video/BV1Ecu66TEiv" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Ecu66TEiv</a></p><p><a href="https://beta.enka.network/endfield/aic/?id=q3e3T5D5Q6d0K7" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=q3e3T5D5Q6d0K7</a></p><p><span id="source-block-q8wRFhJsdttOEPgUXXKzWs"></span></p><h3 id="_4-dynamical-analysis-of-production-controlled-by-blocking" tabindex="-1">4 Dynamical Analysis of Production Controlled by Blocking <a class="header-anchor" href="#_4-dynamical-analysis-of-production-controlled-by-blocking" aria-label="Permalink to &quot;4 Dynamical Analysis of Production Controlled by Blocking&quot;">​</a></h3><p>This section offers theoretical numerical analysis and mathematical derivations/proofs of conclusions used in production design. Designing blocking-based lines does not require mastering it; knowing the conclusions suffices.</p><p><em>Note: Sections 4.1–4.5 were adapted from the original “Dynamics and Stability of Overflow-Fed Systems v3.pdf” and are therefore labelled AI Content.</em></p><details><summary><u>A Note on AI Content in This and Subsequent Sections</u></summary><p>Because my time or ability is limited, some sections were written directly by AI after extensive discussion with me. These are labelled “(AI Content),” with some comments from me at the start of each section. They broadly reflect the questions I want to discuss; I have read through them and think they are basically fine, without major problems. Apart from extremely mathematical proofs (we physicists don&#39;t worry about those.jpg) or particularly difficult problems (which I am still learning about too), I can also take responsibility for explaining them and answering questions.</p><p>In fact, I think the AI writes much better than I do: the logic is complete, the explanations are clear, the labels are explicit, and there are quite a few numerical examples and figures.</p></details><p><a href="/endfield-skydoc/4-0-building-the-science-of-blocking-based-production-on-blocking-flow">4.0 Building Production Controlled by Blocking on the Foundations of Blocking-Flow Theory (Slow Updates)</a> · <a href="/endfield-skydoc/4-1-modeling-blocking-based-production-dynamics-discrete-continuous-and">(Old) 4.1 Modeling Production Dynamics Controlled by Blocking: From Discrete and Continuous Models to Machine Dynamical Systems</a> · <a href="/endfield-skydoc/4-1-blocking-production-as-a-dynamical-system">4.1 How Production Controlled by Blocking Becomes a Dynamical System (AI Content)</a> · <a href="/endfield-skydoc/4-2-two-inputs-two-products-stable-balancing">4.2 Two Inputs, Two Products: How to Achieve Stable Production Balancing (AI Content)</a> · <a href="/endfield-skydoc/4-3-intermediate-products-feedback-and-stability">4.3 How Intermediate Products Change Feedback and Stability (AI Content)</a> · <a href="/endfield-skydoc/4-4-multi-input-priority-design-and-stability-limits">4.4 Multi-Input Systems: Priority Design and the Limits of Stability (AI Content)</a> · <a href="/endfield-skydoc/4-5-empty-storage-startup-and-long-term-operation">4.5 From Empty-Storage Startup to Long-Term Operation: What Ultimately Happens to a Production Line? (AI Content)</a> · <a href="/endfield-skydoc/4-6-equivalence-between-adaptive-operation-and-solving-linear-systems">4.6 Equivalence between Adaptive Operation and Solving Systems of Linear Equations</a></p><p><span id="source-block-BGhIinqSTRKJwiW5DcmrR3"></span></p><h3 id="_5-analysis-of-blocking-feedback-oscillations" tabindex="-1">5 Analysis of Blocking-Feedback Oscillations <a class="header-anchor" href="#_5-analysis-of-blocking-feedback-oscillations" aria-label="Permalink to &quot;5 Analysis of Blocking-Feedback Oscillations&quot;">​</a></h3><p>This section focuses on quantitatively analyzing oscillations caused by blocking: their origins, amplitude and phase calculations, and how they propagate between modules. Read it if, beyond average flow rates, you also need to calculate periods, buffer behavior and related properties.</p><p><a href="/endfield-skydoc/5-0-what-do-we-mean-by-oscillations">5.0 What Exactly Are We Discussing When We Talk about Oscillations?</a> · <a href="/endfield-skydoc/where-do-the-oscillations-come-from">5.1 Where Do the Oscillations Come From?</a> · <a href="/endfield-skydoc/oscillation-properties-of-automatic-activation-structures">5.2 Analyzing Oscillations in an Automatic Activation Setup</a> · <a href="/endfield-skydoc/coarse-grained-modeling-based-on-response-delay">5.3 Coarse-Grained Modeling Based on Response Delay (AI Content)</a> · <a href="/endfield-skydoc/will-oscillatory-input-be-further-amplified">5.4 Will Oscillating Input Be Amplified Further? (AI Content)</a> · <a href="/endfield-skydoc/ko-s-workshop">ko Bird&#39;s Studio</a></p><p><span id="source-block-X2BQguP94yFfFweLbHLcF1"></span></p><h2 id="from-zero-activator-waste-to-broader-adaptive-operation" tabindex="-1">From Zero Activator Waste to Broader Adaptive Operation <a class="header-anchor" href="#from-zero-activator-waste-to-broader-adaptive-operation" aria-label="Permalink to &quot;From Zero Activator Waste to Broader Adaptive Operation&quot;">​</a></h2><blockquote><p>Detailed device explanations have moved to <a href="/endfield-skydoc/some-simpler-adaptive-setups">Some Simpler Zero-Waste Setups</a>.</p></blockquote><p>“<strong>Switch between two states through a blocking signal</strong>, itself controlled by the remaining inventory, thereby forming feedback. The final result is stable oscillation: the relative times spent producing and stopped <strong>adaptively establish the required ratio</strong>.” — kokobird</p><p><span id="source-block-mMMJhvpB2nsi8tOedocEpS"></span></p><h2 id="long-period-reaction-oscillation" tabindex="-1">Long-Period Reaction Oscillation <a class="header-anchor" href="#long-period-reaction-oscillation" aria-label="Permalink to &quot;Long-Period Reaction Oscillation&quot;">​</a></h2><p>This topic requires either of two premises (feasibility: 1&gt;2):</p><p>1. The production side&#39;s range of adaptation to inputs covers the oscillation between both states.</p><p>2. Additional buffering lets machines consume stored inputs during accumulation, and excessive machine input does not waste material. (There is a risk of the control being overwhelmed.)</p><p>We have three signal-detection methods: the <strong>full-storage signal</strong> and <strong>empty-storage signal</strong>, which detect depot inventory, and a manually controlled <strong>clock signal</strong>. Pairing them produces long-period oscillations that keep inputs in storage. This reduces the additional unloaders needed for balancing with empty storage, and also reduces losses where direct full-storage overflow, affected by the withdrawal waveform, prevents material being deposited at its origin.</p><p><span id="source-block-RbO6Tb93wuoHSR4UjEgOUb"></span></p><h3 id="full-storage–clock-control" tabindex="-1">Full-Storage–Clock Control <a class="header-anchor" href="#full-storage–clock-control" aria-label="Permalink to &quot;Full-Storage–Clock Control&quot;">​</a></h3><p>Design sequence: detect failure to deposit into storage (full) → admit reaction inputs and increase consumption → store the signal in a clock and delay it → stop the reaction and begin accumulation. This is one operating cycle.</p><p>Diagram:</p><p><span id="source-block-qGkAB86pF3OMhnOvn3sHBM"></span></p><h3 id="empty-storage–clock-control" tabindex="-1">Empty-Storage–Clock Control <a class="header-anchor" href="#empty-storage–clock-control" aria-label="Permalink to &quot;Empty-Storage–Clock Control&quot;">​</a></h3><p>Design sequence: detect a gap in withdrawal (empty storage) → block reaction inputs and begin accumulation → store the signal in a clock and delay it → start the reaction and increase consumption. This is one operating cycle.</p><p>Diagram:</p><p><span id="source-block-xCX4qF1TzuYffAYgPKb9Pg"></span></p><h3 id="full-storage–empty-storage-control" tabindex="-1">Full-Storage–Empty-Storage Control <a class="header-anchor" href="#full-storage–empty-storage-control" aria-label="Permalink to &quot;Full-Storage–Empty-Storage Control&quot;">​</a></h3><p>Design sequence: detect failure to deposit (full storage) → admit reaction inputs and increase consumption → detect a gap in withdrawal (empty storage) → block reaction inputs and begin accumulation. This is one operating cycle.</p><p>Diagram:</p><p><span id="source-block-Bu1wyct41RhwxXeUeBGarA"></span></p><h3 id="clock–clock-control" tabindex="-1">Clock–Clock Control <a class="header-anchor" href="#clock–clock-control" aria-label="Permalink to &quot;Clock–Clock Control&quot;">​</a></h3><p><s>This seems bizarre, buddy. Why not simply rate-limit to 30p/q unit/min.jpg</s></p><p>Following the preceding discussion, add clocks both before and after blocking. This effectively controls accumulation duration T1 s and overconsumption duration T2 s. The controlled factory consumes at v unit/min. T1 and T2 can be changed through the clock structures and contents. For identical structures, assuming a constant signal-propagation delay t s, consumption is vT2/(T1+T2+t) unit/min, allowing some degree of p/q consumption limiting.</p><hr><p>The digital-circuit material has moved to <a href="/endfield-skydoc/digital-circuits">Digital Circuits</a>.</p></div>',1)])])}const g=o(n,[["render",r]]);export{u as __pageData,g as default};
